import{_ as b,o as a,c,y as d}from"./chunks/framework.CNTkXYA8.js";const l=JSON.parse('{"title":"【数论】如何证明gcd/exgcd","description":"","frontmatter":{"title":"【数论】如何证明gcd/exgcd","date":"2019-10-03T19:28:00.000Z"},"headers":[],"relativePath":"blog/gcd-exgcd.md","filePath":"source/old_posts/gcd-exgcd.md"}'),o={name:"blog/gcd-exgcd.md"};function g(m,p,e,t,n,x){return a(),c("div",null,[...p[0]||(p[0]=[d("<p>我恨数论</p><p>因为打这篇的时候以为a|b是a是b的倍数，但是懒得改了，索性定义 a|b 为 a是b的倍数</p><p>咳咳，那么进入正题，如何证明gcd，也就是 gcd(a,b) = gcd(b,a%b)？</p><p>首先，设</p><p>p = a/b,c = a mod b</p><p>则a = p*b + c</p><p>m = gcd(a,b),n = gcd(b,c)</p><p>因为m = gcd(a,b)，所以 a | m 且 b | m</p><p>因为 b | m</p><p>所以 b * p | m // a|b，则a*k|b (k为整数)</p><p>因为a | m</p><p>所以a - b * p | m // a|b，则k*b - a | b (k为整数)</p><p>因为 a = p*b + c</p><p>所以 c = a - p*b</p><p>所以 c | m</p><p>因为c | m，且b | m</p><p>所以m为 c,b的公约数</p><p>因为n为 c,b的最大公约数</p><p>所以m &lt;= n</p><p>因为n = gcd(b,c)</p><p>所以 b | n , c | n</p><p>因为 b | n</p><p>所以 b * p | n</p><p>因为 c | n</p><p>所以 b * p + c | n</p><p>因为 a = b * p + c</p><p>所以a | n</p><p>因为a | n,且 b | n</p><p>则n为a,b的公约数</p><p>因为m为a,b的最大公约数</p><p>所以 n &lt;= m</p><p>因为m &lt;= n</p><p>所以m = n</p><p>所以gcd(a,b) = gcd(b,c)</p><p>所以gcd(a,b) = gcd(b,a%b)</p><p>整体思路是：</p><p>先设出一个关系，然后通过关系证明它们的另一个关系</p><p>从gcd(a,b)转换得到b,c是公约数关系，</p><p>从gcd(b,c)转换得到a,b是公约数关系，</p><p>分别得到它们的大小关系，最后求公共解集，得到两个gcd相等</p><p>然后把c带上去，得到我们要证的式子</p><p>证完了gcd，下面可以证exgcd</p><p>exgcd 可以求</p><p>ax + by = gcd(a,b) 中的x,y</p><p>那么，我们设</p><p>ax1 + by1 = gcd(a,b)</p><p>由gcd得出</p><p>ax1 + by1 = gcd(b,a mod b)</p><p>设bx2 + a mod b y2 = gcd(b,a mod b)</p><p>下面用x2开始化简：</p><p>gcd(b, a mod b) = b * x2 + a mod b *y2</p><p>gcd(b, a mod b) = b * x2 + (a - floor(a/b) * b) * y2</p><p>gcd(b, a mod b) = b * x2 + a * y2 - floor(a/b) * b * y2</p><p>gcd(b, a mod b) = a * y2 + b * x2 - floor(a/b) * b * y2</p><p>gcd(b, a mod b) = a * y2 + b * (x2 - floor(a/b) * y2)</p><p>所以</p><p>ax1 + by1 = gcd(b, a mod b) = bx2 + a mod b y2 = a * y2 + b * (x2 - floor(a/b) * y2)</p><p>所以第一个式子与最后一个式子等量代换得到</p><p>x1 = y2</p><p>y1 = x2 - floor(a/b) * y2</p><p>然后可以通过以上等价式子写出递归，得到x1、y1。</p>",61)])])}const y=b(o,[["render",g]]);export{l as __pageData,y as default};
